  const others=[...areaLookup.value.values()].filter(a=>a.id!==area.id).map(a=>a.geometry.coordinates[0])
  const seed=area.id.split('').reduce((a,c)=>a+c.charCodeAt(0),1)
  illegalRoadSpots.set(area.id,areaSurroundSpots(area.geometry.coordinates[0],[area.longitude,area.latitude],[...buildingRings,...others],{seed}))
 }
