  const ring=area.geometry.coordinates[0].map(p=>map.latLngToContainerPoint([p[1],p[0]])),xy=ring.map(p=>[p.x,p.y]),xs=ring.map(p=>p.x),ys=ring.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys)
