function positionLabels(){if(!map||!data.value)return;const used=[],bounds=new Map([...areaLookup.value.values()].map(a=>{const ring=a.geometry.coordinates[0].map(p=>map.latLngToContainerPoint([p[1],p[0]])),xs=ring.map(p=>p.x),ys=ring.map(p=>p.y);return[a.id,{ring,minX:Math.min(...xs),maxX:Math.max(...xs),minY:Math.min(...ys),maxY:Math.max(...ys)}]}));for(const b of badges){const box=bounds.get(b.area.id),pos=parkingLabelPoint(box.ring,map.getZoom()),w=78*pos.scale,h=34*pos.scale;let x=pos.x,y=pos.y;if(pos.outside){const options=[];for(let i=0;i<7;i++){const shift=(i%2?-1:1)*Math.ceil(i/2)*(w+5);options.push({x:pos.x+shift,y:pos.y},{x:box.maxX+14+w/2,y:(box.minY+box.maxY)/2+shift},{x:box.minX-14-w/2,y:(box.minY+box.maxY)/2+shift},{x:pos.x+shift,y:box.maxY+14+h/2})}const score=p=>{let cost=Math.hypot(p.x-pos.x,p.y-pos.y)*.1;for(const r of used)if(Math.abs(r.x-p.x)<(r.w+w)/2+3&&Math.abs(r.y-p.y)<(r.h+h)/2+3)cost+=10000;for(const r of bounds.values())if(p.x+w/2>r.minX-3&&p.x-w/2<r.maxX+3&&p.y+h/2>r.minY-3&&p.y-h/2<r.maxY+3)cost+=2000;if(p.x<w/2||p.y<h/2||p.x>canvasSize.w-w/2||p.y>canvasSize.h-h/2)cost+=300;return cost};options.sort((a,b)=>score(a)-score(b));({x,y}=options[0])}else for(let step=0;step<12&&used.some(r=>Math.abs(r.x-x)<(r.w+w)/2+3&&Math.abs(r.y-y)<(r.h+h)/2+3);step++)x=pos.x+(step%2?-1:1)*Math.ceil((step+1)/2)*(w+5);used.push({x,y,w,h});b.marker.setLatLng(map.containerPointToLatLng([x,y]));b.node.style.setProperty('--badge-scale',pos.scale);if(pos.outside){const anchor=[Math.max(box.minX,Math.min(box.maxX,x)),Math.max(box.minY,Math.min(box.maxY,y))];b.leader.setLatLngs([map.containerPointToLatLng(anchor),map.containerPointToLatLng([x,y])]);b.leader.setStyle({opacity:.55})}else b.leader.setStyle({opacity:0})}}

function updateStats(){if(!data.value)return;const {loads,illegal}=parkingTotals(agents.value,simTime,1),zones={'食堂':0,'修远':0,'明远':0,'鸿远':0};let moving=0;for(const a of agents.value){if(simTime<a.start||simTime>=arrivalTime(a,data.value.paths))continue;moving++;const st=phase(a,simTime,data.value.paths);if(st.kind==='dining'||(st.kind==='moving'&&st.leg==='canteen'))zones['食堂']++;else{const z=(a.destination_name||'').slice(0,2);if(zones[z]!=null)zones[z]++}}stats.value={loads,illegal,moving,parked:Math.round(Object.values(loads).reduce((a,b)=>a+b,0)),over:data.value.areas.filter(a=>(loads[a.id]||0)>a.capacity).length,zones,zoneDetails:zoneDetailsAt(agents.value,simTime,data.value.paths)};time.value=simTime;for(const g of groups){zoneHistory[g]=(data.value.timeline?.[scenario.value]||[]).filter(r=>r.time<=simTime).map(r=>r.zones[g].active)}drawTrends();updateAccidents();for(const b of badges){const m=metricFor(b.area),text=m.percent+'%',sub=`违停 ${m.illegal} · ${m.illegalRate}%`;if(b.valueNode.textContent!==text)b.valueNode.textContent=text;if(b.illegalNode.textContent!==sub)b.illegalNode.textContent=sub;const color=colorFor(m.percent);if(b.color!==color){b.color=color;b.node.style.setProperty('--pin-color',color);b.node.style.setProperty('--pin-bg',bgFor(m.percent));b.layer.setStyle({color,fillOpacity:m.percent>=100?.25:.1})}}fleetDirty=true}
function setTrend(g){return c=>{if(c)trendCanvas[g]=c}}
function drawTrends(){for(const g of groups){const c=trendCanvas[g];if(!c)continue;const ctx=c.getContext('2d'),h=zoneHistory[g];ctx.clearRect(0,0,c.width,c.height);const max=Math.max(10,...h);ctx.fillStyle=getComputedStyle(c).color||'#6d9470';const w=c.width/61;for(let i=0;i<h.length;i++){const bh=Math.max(1,h[i]/max*(c.height-3));ctx.fillRect(i*w,c.height-bh,Math.max(1,w-1),bh)}}}
