function paintFleet(){clear(fleetCanvas);const ctx=context(fleetCanvas),zoom=map.getZoom(),size=zoom>=18?.86:zoom>=17?.68:.4;if(!showLots.value)return;const keep=zoom>=17?1:zoom>=16?.5:zoom>=15?.25:.12;for(const a of (zoom>=18?agents.value:visibleAgents.value)){if((Math.imul(a.id+1,2654435761)>>>0)%100>=keep*100)continue;if(a.area_id&&simTime>=a.start+a.travel_seconds+(a.parking_seconds??18)){const p=parkedPoint(a);if(p&&onScreen(p))drawActor(ctx,p,a.mode,size*.72,0,1,false,0)}else if(a.via_area_id&&simTime>=a.start+a.leg1_seconds+18&&simTime<a.start+a.leg1_seconds+a.dwell_seconds){const p=diningSpot(a);if(p&&onScreen(p))drawActor(ctx,p,a.mode,size*.72,0,1,false,0)}}}
