  drawDotFlow(ctx,p=>routes.sample(st.path,p),st.progress,mode,1,members.length,Math.min(.08,8/Math.max(20,length)))
  if(zoom<18){const previous=routes.sample(st.path,Math.max(0,st.progress-.005));drawActor(ctx,point,mode,.42,Math.atan2(point.y-previous.y,point.x-previous.x),1,true,simTime)}
 }
