function draw(now){frame=requestAnimationFrame(draw);if(!map||!data.value||mapMoving){previous=now;return}if(now-lastRender<1000/30)return;lastRender=now;if(!playing.value&&!needsPaint){previous=now;return}const delta=previous?Math.min((now-previous)/1000,.2):0;previous=now;if(playing.value){simTime=Math.min(1800,simTime+delta*speed.value);if(simTime===1800)playing.value=false}if(now-lastStats>250||needsPaint){updateStats();lastStats=now}if(fleetDirty){paintFleet();fleetDirty=false}if(now-lastFlow>65||needsPaint){paintFlows();lastFlow=now}needsPaint=false;const ctx=context(canvas.value);clear(canvas.value);const zoom=map.getZoom(),size=zoom>=18?.86:zoom>=17?.68:.48;for(const a of visibleAgents.value){const state=phase(a,simTime,data.value.paths);if(zoom<18&&['moving','walking'].includes(state.kind))continue;let p,angle=0,alpha=1;if(state.kind==='dining'){const end=pixel(a.via_path,1);p={x:end.x+10*size,y:end.y+8*size};if(onScreen(p)&&zoom>=17){ctx.font='11px "PingFang SC","HarmonyOS_Regular","Helvetica Neue","Microsoft YaHei",sans-serif';ctx.fillStyle='#8a6d3b';ctx.fillText('用餐',p.x+10,p.y-13)}}else if(state.kind==='parking'){const spot=parkedPoint(a);if(!spot)continue;p=lerp(pixel(a.path,1),spot,1-Math.pow(1-state.progress,2))}else if(state.kind==='dismount'){const spot=parkedPoint(a);if(!spot)continue;p={x:spot.x+14*size,y:spot.y-5*size};alpha=Math.min(1,state.progress*4);if(onScreen(p)&&zoom>=17){ctx.font='11px "PingFang SC","HarmonyOS_Regular","Helvetica Neue","Microsoft YaHei",sans-serif';ctx.fillStyle='#79583d';ctx.fillText('下车',p.x+10,p.y-13)}}else if(state.kind==='leaving'){const spot=parkedPoint(a);if(!spot)continue;const side={x:spot.x+14*size,y:spot.y-5*size};p=lerp(side,a.walk_path?pixel(a.walk_path,0):side,state.progress)}else if(state.kind==='entering'){const end=pixel(a.walk_path||a.path,1),goal=destinationLookup.value.get(a.destination_id),dest=goal?map.latLngToContainerPoint([goal.latitude,goal.longitude]):end;p=lerp(end,dest,state.progress);alpha=1