function buildLots(){lotLayer.clearLayers();badgeLayer.clearLayers();badges=[];for(const area of areaLookup.value.values()){const layer=L.geoJSON(area.geometry,{style:{color:'#22804a',weight:1.7,fillOpacity:.1}}).addTo(lotLayer);layer.on('click',()=>focus(area));const node=document.createElement('button');node.className='sim-parking-pin';node.title=area.name;node.setAttribute('aria-label',area.name);const letter=document.createElement('b');letter.textContent='P';const numbers=document.createElement('span'),valueNode=document.createElement('strong'),illegalNode=document.createElement('small');numbers.append(valueNode,illegalNode);node.append(letter,numbers);node.onclick=()=>focus(area);const marker=L.marker([area.latitude,area.longitude],{icon:L.divIcon({html:node,className:'sim-parking-icon',iconSize:[0,0]}),title:area.name}).addTo(badgeLayer),leader=L.polyline([],{color:'#74796c',weight:1,dashArray:'3 4',interactive:false}).addTo(badgeLayer);const tooltip=document.createElement('span');tooltip.textContent=area.name;marker.bindTooltip(tooltip,{direction:'top'});badges.push({area,node,valueNode,illegalNode,marker,leader,layer})}toggleLots();positionLabels()}
