  const node=document.createElement('button');node.className='sim-camera';node.textContent='📹';node.setAttribute('aria-label',camera.name)
  const tip=document.createElement('span');tip.textContent=`${camera.building}外角立面约${camera.height_m}米 · 摄像头规划点 · 扇形覆盖${Math.round(camera.radius)}米 · ${camera.group==='修远'?'点击查看样本画面':'视频接口预留'}`
  L.marker([camera.point[1],camera.point[0]],{icon:L.divIcon({html:node,className:'sim-camera-icon',iconSize:[0,0]}),title:camera.name}).bindTooltip(tip,{direction:'top'}).addTo(cameraLayer)
