function buildAccidents(){accidentLayer.clearLayers();accidentMarkers=[];for(const a of (data.value?.accidents?.[scenario.value]||[])){const node=document.createElement('div');node.className='sim-accident';node.innerHTML='<b>⚠</b><span>事故</span>';const tip=document.createElement('span');tip.textContent=`${a.road_name||'通用道路'} · 模拟事故（${a.kind==='junction'?'路口':'路段'}）${clockOf(a.start)}—${clockOf(a.end)} · 情景模型，非真实事件`;const marker=L.marker([a.latitude,a.longitude],{icon:L.divIcon({html:node,className:'sim-accident-icon',iconSize:[0,0]}),interactive:true}).bindTooltip(tip,{direction:'top'});const halo=L.circle([a.latitude,a.longitude],{radius:28,color:'#cc7765',weight:1,fillColor:'#dc8c7b',fillOpacity:.055,interactive:false});const zone=L.layerGroup([halo,marker]);accidentMarkers.push({a,marker:zone,on:false})}
