 updateAccidents()}
function focus(area){selected.value=area;map.flyTo([area.latitude,area.longitude],19,{duration:.7})}
function toggleLots(){if(!map)return;for(const [layer,visible] of [[lotLayer,showLots.value],[badgeLayer,showMetrics.value]]){if(visible)layer.addTo(map);else map.removeLayer(layer)}fleetDirty=true;needsPaint=true}
function fit(){if(!data.value)return;const bounds=L.latLngBounds([...areaLookup.value.values()].flatMap(a=>a.geometry.coordinates[0].map(p=>[p[1],p[0]])));for(const a of agents.value){const p=data.value.paths[a.path].coordinates[0];bounds.extend([p[1],p[0]])}const narrow=map.getSize().x<720;map.fitBounds(bounds,{paddingTopLeft:[20,100],paddingBottomRight:[narrow?20:280,narrow?250:175],maxZoom:17})}
function restart(){simTime=0;time.value=0;playing.value=true;previous=0;needsPaint=true;for(const g of groups)zoneHistory[g]=[];updateStats()}
function seek(){simTime=time.value;previous=0;needsPaint=true;lastFlow=0;for(const g of groups)zoneHistory[g]=[];updateStats()}
function togglePlay(){playing.value=!playing.value;previous=0;needsPaint=true}
function navPlaying(resume){if(resume){if(navPaused.value){navPaused.value=false;playing.value=true;previous=0;needsPaint=true}}else{navPaused.value=true;if(playing.value){playing.value=false;needsPaint=true}}}
function switchCase(value){scenario.value=value;selected.value=null;buildAccidents();restart()}
async function load(){controller?.abort();controller=new AbortController();const token=controller;loading.value=true;error.value='';try{const r=await fetch('/api/simulation/morning?population=4000&count='+count.value,{signal:controller.signal});const d=await r.json();if(!r.ok)throw Error(d.detail||'交通动画加载失败');if(disposed||token!==controller)return;data.value=d;illegalRoadSpots.clear();routes=new ScreenRoutes(map,d.paths);parkSpots.clear();placeLayer.clearLayers();for(const [items,tone] of [[d.origins||[],'#6e7e65'],[d.destinations||[],'#8e7858'],[d.canteens||[],'#b07a2a']])for(const p of items){const label=document.createElement('span');label.textContent=p.name;L.circleMarker([p.latitude,p.longitude],{radius:3,color:'white',weight:1,fillColor:tone,fillOpacity:1}).bindTooltip(label,{direction:'top'}).addTo(placeLayer)}buildLots();buildCameras();buildAccidents();fit();restart()}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{if(token===controller)loading.value=false}}
function settings(){const value=Number(localStorage.getItem('campusflow.animation.count'));if(value>=100&&value<=1000&&value!==count.value){count.value=value;needsPaint=true;fleetDirty=true;lastFlow=0}}
function addCanvas(name,z,existing){const pane=map.createPane(name);pane.style.zIndex=z;pane.style.pointerEvents='none';const c=existing||document.createElement('canvas');c.className='traffic-canvas';pane.appendChild(c);return c}
onMounted(async()=>{map=L.map(el.value,{zoomControl:false,zoomSnap:.25,center:[34.372,108.899],zoom:16});sharedMap.value=map;flowCanvas=addCanvas('traffic-paths',440);fleetCanvas=addCanvas('traffic-parked',450);addCanvas('traffic-actors',460,canvas.value);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,maxNativeZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);lotLayer=L.layerGroup().addTo(map);badgeLayer=L.layerGroup().addTo(map);placeLayer=L.layerGroup().addTo(map);cameraLayer=L.layerGroup().addTo(map);accidentLayer=L.layerGroup().addTo(map);map.on('movestart zoomstart',()=>{mapMoving=true});map.on('resize',projection);map.on('moveend zoomend',()=>{mapMoving=false;projection();positionLabels();needsPaint=true});resize=new ResizeObserver(()=>{map.invalidateSize();projection();positionLabels()});resize.observe(el.value);projection();frame=requestAnimationFrame(draw);document.fonts.ready.then(()=>{if(!disposed){needsPaint=true;fleetDirty=true}});window.addEventListener('storage',settings);try{const r=await fetch('/api/navigation/map');if(!r.ok)throw Error('道路图层加载失败');const d=await r.json();if(disposed)return;roadFeatures=d.features||[];const names=new Set();L.geoJSON(d,{style:f=>({color:f.properties.name==='修远大道'?'#e9a149':f.properties.highway==='cycleway'?'#339361':['footway','pedestrian','steps'].includes(f.properties.highway)?'#a3947c':'#e9a149',weight:3,opacity:.8}),onEachFeature(f,l){const n=f.properties.name;if(n&&!names.has(n)){names.add(n);const text=document.createElement('span');text.textContent=n;l.bindTooltip(text,{permanent:true,direction:'center',className:'sim-road-name'})}}}).addTo(map);const b=await fetch('/api/navigation/buildings');if(b.ok){const bd=await b.json();buildingFeatures=bd.features||[];buildingRings=(bd.features||[]).map(f=>f.geometry?.coordinates?.[0]).filter(r=>r?.length>=3)}await load()}catch(e){error.value=e.message;loading.value=false}})
onBeforeUnmount(()=>{disposed=true;controller?.abort();cancelAnimationFrame(frame);window.removeEventListener('storage',settings);resize?.disconnect();map?.remove()})
</script>
<template>
 <div class="morning-app">
  <div ref="el" class="morning-map"></div><canvas ref="canvas" class="traffic-canvas" aria-label="沿校园路网运行的行人、自行车和电动车交通动画"></canvas>
  <header class="morning-header"><div><strong>CampusFlow</strong><span>渭水校区 / 早高峰交通演示</span></div><nav><button :class="{chosen:scenario==='baseline'}" @click="switchCase('baseline')">01 原有停车习惯</button><button :class="{chosen:scenario==='guided'}" @click="switchCase('guided')">02 系统引导分流</button></nav></header>
  <aside class="morning-explainer"><small>08:00—08:30 · 校园早高峰</small><h1>{{scenario==='baseline'?'人流汇入，停车失衡':'改变停车选择，缓解集中'}}</h1><p>宿舍出发 → 就近食堂（部分经停用餐）→ 沿路网通行 → 停车 → 步行至教学楼</p><div class="type-key"><span style="color:#725aad">● 行人 · 紫色点阵</span><span style="color:#198755">● 自行车 · 绿色点阵</span><span style="color:#dc6c24">● 电动车 · 橙色点阵</span></div><p>点击 P 放大：看车辆汇入、停下与人车分离。橙红粗线表示缓行/拥堵，⚠表示事故位置。拖动时间可回看停车形成过程。</p><label><input type="checkbox" v-model="showLots" @change="toggleLots">停车区域与车辆</label><label><input type="checkbox" v-model="showMetrics" @change="toggleLots">容载率与违停率</label>
   <section v-if="caseMetrics" class="compare-block"><h2>01 与 02 情景对比</h2><table><tbody>
    <tr><th></th><th :class="{now:scenario==='baseline'}">01 原有</th><th :class="{now:scenario==='guided'}">02 引导</th></tr>
    <tr><td>平均全程耗时</td><td>{{caseMetrics.baseline.trip.toFixed(1)}} 分</td><td>{{caseMetrics.guided.trip.toFixed(1)}} 分</td></tr>
    <tr><td>平均停车后步行</td><td>{{caseMetrics.baseline.walk.toFixed(1)}} 分</td><td>{{caseMetrics.guided.walk.toFixed(1)}} 分</td></tr>
    <tr><td>模拟事故</td><td>{{caseMetrics.baseline.accidents}} 起</td><td>{{caseMetrics.guided.accidents}} 起</td></tr>
    <tr v-if="caseMetrics.baseline.delay_minutes!=null"><td>平均拥堵延误</td><td>{{caseMetrics.baseline.delay_minutes.toFixed(1)}} 分</td><td>{{caseMetrics.guided.delay_minutes.toFixed(1)}} 分</td></tr>
    <tr><td>高负载车行路段</td><td>{{caseMetrics.baseline.congested}} 段</td><td>{{caseMetrics.guided.congested}} 段</td></tr>
    <tr><td>最终超容量停车区</td><td>{{caseMetrics.baseline.over}} 处</td><td>{{caseMetrics.guided.over}} 处</td></tr>
   </tbody></table><p class="compare-note">{{takeaway}}</p></section>
   <a href="/debug" target="_blank" rel="noopener">调试动效数量 ↗</a><button class="bus-edit" @click="editingBus=true">编辑公交线路、站点与车辆</button></aside>
  <div v-if="loading||error" class="morning-message" role="status">{{error||'正在按校园路网生成出行轨迹…'}}<button v-if="error" @click="load">重新加载</button></div>
  <aside v-if="selected" class="parking-closeup"><button class="close" @click="selected=null">×</button><small>停车区近景</small><h2>{{selected.name}}</h2><strong v-if="showMetrics">{{metricFor(selected).percent}}%</strong><p v-if="showMetrics">停放 {{metricFor(selected).total}} / 容量 {{selected.capacity}}<br>违停 {{metricFor(selected).illegal}} 辆 · {{metricFor(selected).illegalRate}}%</p><p>车辆进入停车区并停下，人在车旁出现，再走向教学楼。区域外车辆为归属该停车区的违停车辆。</p></aside>
  <div v-if="cameraShot" class="camera-modal" @click.self="cameraShot=null"><div class="camera-card"><button class="close" @click="cameraShot=null">×</button><small>修远区域 · 视觉识别覆盖</small><h2>{{cameraShot.name}}</h2><img :src="cameraShot.src" alt="修远停车区摄像头实拍画面"><p>停车拥挤度由摄像头视觉算法估算；此处为实拍样本演示，正式视频流接口已预留，接入后显示实时画面。</p></div></div>
  <footer class="morning-footer"><div class="time-controls"><button @click="togglePlay" :disabled="!data">{{playing?'暂停':'播放'}}</button><button @click="restart" :disabled="!data">重播</button><b>{{clock}}</b><input aria-label="早高峰时间轴" type="range" min="0" max="1800" step="1" :disabled="!data" v-model.number="time" @input="seek"><select v-model.number="speed" aria-label="播放速度"><option :value="10">10倍</option><option :value="20">20倍</option><option :value="40">40倍</option><option :value="60">60倍</option></select></div>
   <div class="traffic-summary"><div class="summary-total"><span>总体交通状态</span><b>{{stats.moving}} 人在途 · {{stats.parked}} 辆停放</b><small>{{stats.over}} 处超容量 · {{data?.generated_agents||0}} 人 · {{data?.vehicle_count||0}} 辆车 · 图标上限 {{count}}</small></div><div v-for="g in groups" :key="g" class="flow-group"><span>{{g==='食堂'?'食堂餐饮区':g+'教学片区'}}</span><div class="zone-chart"><i class="zone-bar" :class="zoneClass(g)" :style="{height:zoneBar(g)}"></i><i class="zone-bar source-two" :class="zoneClass(g)" :style="{height:zoneBar(g,true)}"></i><canvas width="140" height="30" :ref="setTrend(g)" :class="zoneClass(g)"></canvas></div><small>{{stats.zones[g]||0}} 人{{g==='食堂'?'用餐/前往':'在途前往'}}</small><small v-if="g==='食堂'" class="zone-sources">近1分钟 到店 {{zoneDetails(g).incoming}} · 离店 {{zoneDetails(g).outgoing}}</small><small v-else class="zone-sources">宿舍→{{zoneDetails(g).dorm_source}} · 食堂→{{zoneDetails(g).canteen_source}} · 已到{{zoneDetails(g).arrived}}</small></div><div class="road-types"><span><i style="background:#339361"></i>自行车道</span><span><i style="background:#e9a149"></i>通用道路</span><span><i style="background:#a3947c"></i>步行道</span></div></div>
   <p class="simulation-source">统计按每辆车逐辆计算；地图图标为抽样展示；食堂经停、缓行与事故均为情景模型。<br>{{data?.covered_dorms||0}} 栋宿舍 · {{data?.canteens?.length||0}} 个食堂 · 轨迹抵达目的地后延迟消失 <span v-if="data?.excluded.length">· {{data.excluded.length}} 条需求暂不可达</span></p>
  </footer>
  <NavigationApp v-if="sharedMap" :shared-map="sharedMap" always-on :traffic-context="{time_seconds:time,scenario,count,seed:data?.seed||20261016,population:data?.population||4000}" @playing-change="navPlaying"/>
  <TransitWorkbench v-if="editingBus" @close="editingBus=false"/>
 </div>
</template>
