lock th,.compare-block td{padding:4px 2px;text-align:right;color:#5c665c}.compare-block th:first-child,.compare-block td:first-child{text-align:left;color:#838a7d}.compare-block th.now,.compare-block td:has(+ td),.compare-block .now{color:#375b47;font-weight:700}.compare-block th{font-weight:600}.compare-note{font-size:11px;color:#375b47!important;background:#e8f1e9;border-radius:6px;padding:7px 9px;line-height:1.6!important}.morning-footer{position:absolute;bottom:18px;left:22px;right:70px;z-index:700;background:#fffef8f5;border:1px solid #dadbd1;border-radius:8px;box-shadow:0 4px 20px #26362820;padding:13px 18px 8px}.time-controls{display:flex;gap:10px;align-items:center}.time-controls b{font:24px var(--app-font);font-variant-numeric:tabular-nums;min-width:100px}.time-controls input{flex:1;accent-color:#416b51;min-width:50px}.time-controls select{border:1px solid #d5d9cb;padding:7px;background:#fffef8;border-radius:4px}.traffic-summary{display:flex;justify-content:space-between;align-items:center;gap:20px;border-top:1px solid #e5e7dc;margin-top:12px;padding-top:12px}.summary-total{display:grid;gap:3px}.summary-total span,.flow-group>span{font-size:11px;color:#777f70}.summary-total b{font-size:14px;font-weight:500}.summary-total small,.flow-group small{font-size:10px;color:#838a7d}.flow-group{min-width:120px}.zone-chart{display:flex;align-items:flex-end;gap:8px;height:34px}.zone-bar{width:14px;border-radius:3px 3px 0 0;transition:height .3s}.zone-bar.z-canteen{background:#b07a2a}.zone-bar.z-xiuyuan{background:#4a7d5d}.zone-bar.z-mingyuan{background:#6a7fb5}.zone-bar.z-hongyuan{background:#b0654a}.zone-chart canvas{height:30px;width:140px}.zone-chart canvas.z-canteen{color:#b07a2a}.zone-chart canvas.z-xiuyuan{color:#4a7d5d}.zone-chart canvas.z-mingyuan{color:#6a7fb5}.zone-chart canvas.z-hongyuan{color:#b0654a}.road-types{font-size:10px;display:grid;gap:5px;white-space:nowrap}.road-types i{display:inline-block;width:20px;height:3px;margin-right:6px;vertical-align:mid