anslate(-50%,-50%);font-size:13px;background:#eef4fb;border:1.5px solid #3f7ec2;color:#3f7ec2;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;padding:0;cursor:pointer;box-shadow:0 1px 5px #3f7ec240}.camera-modal{position:absolute;inset:0;z-index:900;background:#1d24207a;display:flex;align-items:center;justify-content:center}.camera-card{background:#fffef8;border-radius:10px;padding:22px;width:min(560px,86vw);box-shadow:0 10px 40px #0004;position:relative}.camera-card small{color:#8b8065}.camera-card h2{font-size:18px;margin:8px 0 12px}.camera-card img{width:100%;border-radius:8px;border:1px solid #dcdccb}.camera-card p{font-size:12px;color:#747c70;line-height:1.8;margin:10px 0 0}.camera-card .close{position:absolute;right:14px;top:10px;border:0;font-size:22px;background:none}@keyframes traffic-wave{to{transform:scaleY(.35)}}@keyframes accident-pulse{to{transform:translate(-50%,-50%) scale(1.18);box-shadow:0 1px 12px #d9302566}}@media(max-width:950px){.morning-header{align-items:start}.morning-header span{display:none}.morning-header nav{flex-wrap:wrap;max-width:55%}.morning-explainer{width:210px;top:108px}.traffic-summary{gap:10px}.flow-group{min-width:70px}.zone-chart canvas{width:70px}.road-types{display:none}}@media(max-width:650px){.morning-header{left:10px;right:10px}.morning-header nav{font-size:10px}.morning-header strong{font-size:18px}.morning-explainer{right:10px;width:170px;padding:12px}.morning-explainer h1{font-size:15px}.morning-explainer p{display:none}.morning-footer{left:10px;right:45px;bottom:10px;padding:10px}.time-controls{gap:5px}.time-controls b{font-size:18px;min-width:75px}.time-controls button{padding:6px}.traffic-summary{flex-wrap:wrap}.summary-total{width:100%}.flow-group{flex:1}.parking-closeup{left:10px;top:100px;width:170px;padding:12px}.simulation-source{font-size:9px}}
